module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

    reg res_valid_reg;
    reg start_cnt;
    reg [3:0] cnt;
    reg [7:0] neg_divisor;
    reg [7:0] remainder;
    reg [7:0] quotient;
    reg [17:0] SR;
    assign res_valid = res_valid_reg;
    assign result = {remainder, quotient};
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            res_valid_reg <= 1'b0;
        end else begin
            res_valid_reg <= res_valid_reg;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            start_cnt <= 1'b0;
        end else if(opn_valid == 1'b1 && res_valid != 1'b1)begin
            start_cnt <= 1'b1;
        end else begin
            start_cnt <= 1'b0;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            cnt <= 4'd0;
        end else if(start_cnt == 1'b1)begin
            if(cnt[3] == 1'b1)begin
                cnt <= 4'd0;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end else begin
            cnt <= 4'd0;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            neg_divisor <= 8'd0;
        end else if(sign == 1'b1)begin
            neg_divisor <= ~divisor + 1'b1;
        end else begin
            neg_divisor <= ~divisor;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            remainder <= 8'd0;
        end else if(start_cnt == 1'b1)begin
            if(SR[17] == 1'b1)begin
                remainder <= SR + neg_divisor;
            end else begin
                remainder <= SR;
            end
        end else begin
            remainder <= 8'd0;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            quotient <= 8'd0;
        end else if(start_cnt == 1'b1)begin
            if(SR[17] == 1'b1)begin
                quotient[cnt] <= 1'b0;
            end else begin
                quotient[cnt] <= 1'b1;
            end
        end else begin
            quotient <= 8'd0;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            SR <= 18'd0;
        end else if(start_cnt == 1'b1)begin
            if(cnt == 4'd0)begin
                SR <= {dividend, 1'b0};
            end else begin
                SR <= {remainder[16:0], quotient[cnt]};
            end
        end else begin
            SR <= 18'd0;
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst == 1'b1)begin
            res_valid_reg <= 1'b0;
        end else if((res_valid & res_ready) == 1'b1)begin
            res_valid_reg <= 1'b0;
        end else if(cnt == 4'd8)begin
            res_valid_reg <= 1'b1;
        end else begin
            res_valid_reg <= res_valid_reg;
        end
    end
endmodule
